async function api(path,data={}){

 const ut=window.Classes?.token();if(ut&&!data.userToken)data={...data,userToken:ut};
 const ctl=new AbortController(),to=setTimeout(()=>ctl.abort(),120000);let r;try{r=await fetch(path,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(data),signal:ctl.signal})}catch(e){throw Error(e.name==='AbortError'?'This is taking too long. Please try again.':'Could not reach the server. Check your connection.')}finally{clearTimeout(to)}let result;
 try{result=await r.json()}catch{throw Error('Could not reach mission control. Check your connection.')}
 if(r.status===401&&config?.authMode==='classes'&&!path.startsWith('/api/auth/'))Classes.needSignIn(result.error);
 if(!r.ok)throw Error(result.error||'Request failed.');return result;
}
