 const paused=r.paused||r.closed||localPaused||r.game?.phase==='lobby';$('#game-overlay').classList.toggle('hidden',!paused);$('#overlay-title').textContent=r.game?.phase==='lobby'?'🛰️ Waiting for the teacher':r.closed?'Mission closed':r.paused?'Teacher paused the mission':'Expedition paused';$('#overlay-desc').textContent=r.game?.phase==='lobby'?'Invite the crew. Your teacher assigns secret roles and starts the round.':r.game&&localPaused?'Your view is paused, but the round continues. Ask your teacher to pause the room if needed.':r.closed?'Your progress has been saved.':r.paused?'Your teacher will restart the mission shortly.':'Take a breath. Your progress is safe.';$('#resume').classList.toggle('hidden',r.paused||r.closed||r.game?.phase==='lobby');
